-- migrate:no-transaction
-- Step 2 of 5 (orders.public_id): fill existing rows in primary-key ranges. Each batch commits on its
-- own, so row locks last for one batch. Re-running is safe: only rows still NULL are touched.
SET lock_timeout = '2s';

DO $$
DECLARE
  chunk constant bigint := 5000;
  lo bigint;
  hi bigint;
BEGIN
  SELECT min(id), max(id) INTO lo, hi FROM orders;
  IF lo IS NULL THEN
    RETURN;
  END IF;
  WHILE lo <= hi LOOP
    UPDATE orders SET public_id = gen_random_uuid()
    WHERE id >= lo AND id < lo + chunk AND public_id IS NULL;
    COMMIT;
    PERFORM pg_sleep(0.05);  -- breathing room for WAL, replicas and payment writes
    lo := lo + chunk;
  END LOOP;
END
$$;

RESET lock_timeout;

